import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md","lastUpdated":null}'),i={name:"en/faq.md"};function o(r,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="launch-error-the-value-for-version-in-dsh-credentials-yaml-must-be-a-string" tabindex="-1">Launch error: <code>the value for &quot;version&quot; in ~/.dsh/.credentials.yaml must be a string</code> <a class="header-anchor" href="#launch-error-the-value-for-version-in-dsh-credentials-yaml-must-be-a-string" aria-label="Permalink to &quot;Launch error: `the value for &quot;version&quot; in ~/.dsh/.credentials.yaml must be a string`&quot;">​</a></h2><p>This is a dsh kernel config-read failure, not an app bug. Usually the <strong>top-level</strong> <code>version</code> in <code>.credentials.yaml</code> is a number.</p><p>Fix: edit <code>C:\\Users\\&lt;you&gt;\\.dsh\\.credentials.yaml</code> (or your home equivalent) and make the first line a quoted string:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span></span></code></pre></div><p>Save and relaunch. The inner <code>payload.version</code> does not need changing.</p><h2 id="stuck-on-the-loading-spinner-the-ui-never-appears" tabindex="-1">Stuck on the loading spinner, the UI never appears <a class="header-anchor" href="#stuck-on-the-loading-spinner-the-ui-never-appears" aria-label="Permalink to &quot;Stuck on the loading spinner, the UI never appears&quot;">​</a></h2><p>The app resolves the address from dsh printing <code>dsh web: &lt;url&gt;</code>. If there is no URL for a while:</p><ul><li>check the <strong>Terminal</strong> for dsh errors (Settings → Terminal, or <code>Ctrl</code>/<code>Cmd</code> + <code>T</code>);</li><li>check whether the chosen port is busy (it scans upward for a free one);</li><li>confirm the kernel is installed and the working directory exists and is readable.</li></ul><h2 id="f12-console-does-nothing" tabindex="-1">F12 console does nothing <a class="header-anchor" href="#f12-console-does-nothing" aria-label="Permalink to &quot;F12 console does nothing&quot;">​</a></h2><p>Enable <strong>Developer mode</strong> first: Settings → About → turn on “Developer mode”. It is off by default to avoid accidental use.</p><h2 id="why-stop-dsh-before-upgrade-uninstall" tabindex="-1">Why “stop dsh” before upgrade / uninstall <a class="header-anchor" href="#why-stop-dsh-before-upgrade-uninstall" aria-label="Permalink to &quot;Why “stop dsh” before upgrade / uninstall&quot;">​</a></h2><p>On Windows a running dsh locks the kernel module files, blocking replacement/removal. The app stops it first; if a process still holds the files, it detects and asks you to close it.</p><h2 id="update-check-fails-cannot-connect" tabindex="-1">Update check fails / cannot connect <a class="header-anchor" href="#update-check-fails-cannot-connect" aria-label="Permalink to &quot;Update check fails / cannot connect&quot;">​</a></h2><ul><li>Check your network; in Settings switch the kernel registry to <code>npmmirror</code> and retry.</li><li>App and kernel updates use different channels (GitHub / npm). If GitHub is unreachable, the app self-update may fail while the kernel update still works.</li></ul><h2 id="i-want-multiple-instances" tabindex="-1">I want multiple instances <a class="header-anchor" href="#i-want-multiple-instances" aria-label="Permalink to &quot;I want multiple instances&quot;">​</a></h2><p>It is <strong>single-instance</strong> by default: relaunching focuses the existing window instead of opening another. (Different working-directory/port setups may need to disable the current default concurrency guard.)</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Include the log from the <strong>Terminal</strong> (Settings → Terminal) plus the app version and kernel version when reporting to the maintainers.</p>',19)])])}const f=a(i,[["render",o]]);export{p as __pageData,f as default};
